#include <stdio.h>
int main(void) {
    char s[] = "level";
    int i = 0, j = 4, ok = 1;
    while (i < j) {
        if (s[i] != s[j]) { ok = 0; break; }
        i++; j--;
    }
    printf("%d\n", ok);
    return 0;
}

#include <stdio.h>
int main(void) {
    char s[] = "banana";
    int c = 0;
    for (int i = 0; s[i] != '\0'; i++)
        if (s[i] == 'a') c++;
    printf("%d\n", c);
    return 0;
}

