#include <stdio.h>
#include <string.h>
int main(void) {
    char w[] = "racecar";
    int len = (int)strlen(w), ok = 1;
    for (int i = 0; i < len / 2; i++)
        if (w[i] != w[len - 1 - i]) ok = 0;
    printf(ok ? "yes" : "no");
    return 0;
}

