#include <stdio.h>
int main(void) {
    char a[] = "listen", b[] = "silent";
    int c[26] = {0}, ok = 1;
    for (int i = 0; a[i]; i++) c[a[i] - 'a']++;
    for (int i = 0; b[i]; i++) c[b[i] - 'a']--;
    for (int i = 0; i < 26; i++) if (c[i]) ok = 0;
    printf("%d\n", ok);
    return 0;
}

#include <stdio.h>
int main(void) {
    char s[] = "programming";
    int c[26] = {0}, best = 0;
    for (int i = 0; s[i]; i++) c[s[i] - 'a']++;
    for (int i = 1; i < 26; i++)
        if (c[i] > c[best]) best = i;
    printf("%c\n", 'a' + best);
    return 0;
}

